export function tr(text){let value=String(text);if(KO[value])return KO[value];
 value=value.replace(/(\d+) research leads/g,'$1개 조사 대상').replace(/(\d+)% coverage/g,'데이터 충족률 $1%').replace(/Coverage (\d+)%/g,'데이터 충족률 $1%').replace(/China review required/g,'중국 리스크 검토 필요').replace(/China (LOW|MEDIUM|HIGH)/g,(_,x)=>'중국 리스크 '+KO[x]).replace(/COMPANY RESEARCH \/ (Core|Extended|Excluded|Unverified)/g,(_,x)=>'기업 리서치 / '+KO[x]).replace(/Bottleneck score/g,'병목 점수').replace(/Not collected/g,'미수집').replace(/US exchange verification pending/g,'미국 거래소 검증 대기').replace(/Updated /g,'업데이트 ').replace(/ANALYST HYPOTHESIS/g,'분석자 가설').replace(/Potential Fundamental\/Price Divergence/g,'실적 개선·주가 약세 괴리 가능성').replace(/Potential Expectation Risk/g,'과도한 기대 반영 가능성').replace(/☆ Watch company/g,'☆ 관심 기업 추가').replace(/★ Watching/g,'★ 관심 기업 등록됨').replace(/No linked hypothesis/g,'연결된 병목 가설 없음');
 for(const k of ['POWER INFRASTRUCTURE','POWER ARCHITECTURE','ADVANCED PACKAGING','NETWORKING','ENERGY RESILIENCE','THERMAL SYSTEMS'])value=value.replace(k,KO[k]);
 return value;
}
export function localize(root=document.body){for(const e of root.querySelectorAll('option'))if(!e.hasAttribute('value'))e.setAttribute('value',e.textContent);const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const n of nodes){if(n.parentElement?.closest('script,style,textarea,.evidence p,.report'))continue;const raw=n.nodeValue,trimmed=raw.trim();if(trimmed)n.nodeValue=raw.replace(trimmed,tr(trimmed));}
 for(const e of root.querySelectorAll('[aria-label],[title],[placeholder]'))for(const key of ['aria-label','title','placeholder'])if(e.hasAttribute(key))e.setAttribute(key,tr(e.getAttribute(key)));
}
